#include "render/overlay.h"

#include "core/log.h"
#include "render/font8x16.h"

#include <windows.h>
#include <d3d11.h>
#include <dxgi.h>

#include <algorithm>
#include <vector>

// Shader bytecode generated by build.cmd: fxc /Fh out\obj\gen\overlay_{vs,ps}.h (arrays kOverlayVS / kOverlayPS).
#include "overlay_ps.h"
#include "overlay_vs.h"

namespace mc::render {
namespace {

constexpr int kAtlasCols = 16;
constexpr int kAtlasW = kAtlasCols * font::kCellW;                                        // 128
constexpr int kAtlasH = ((font::kCount + kAtlasCols - 1) / kAtlasCols) * font::kCellH;  // 96
constexpr int kMaxQuads = 4096;
constexpr float kPad = 6.0f;
constexpr float kMargin = 8.0f;

struct Vertex {
    float x, y, u, v;
    uint32_t color;  // R8G8B8A8_UNORM byte order: r, g, b, a
};

template <class T>
void SafeRelease(T*& p) {
    if (p) {
        p->Release();
        p = nullptr;
    }
}

// Everything we change, captured before drawing and put back afterwards.
struct SavedState {
    ID3D11RenderTargetView* rtv[D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT] = {};
    ID3D11DepthStencilView* dsv = nullptr;
    UINT numViewports = D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE;
    D3D11_VIEWPORT viewports[D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE] = {};
    UINT numScissors = D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE;
    D3D11_RECT scissors[D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE] = {};
    ID3D11BlendState* blend = nullptr;
    float blendFactor[4] = {};
    UINT sampleMask = 0;
    ID3D11DepthStencilState* depth = nullptr;
    UINT stencilRef = 0;
    ID3D11RasterizerState* raster = nullptr;
    ID3D11VertexShader* vs = nullptr;
    ID3D11ClassInstance* vsInst[256] = {};
    UINT vsInstCount = 256;
    ID3D11PixelShader* ps = nullptr;
    ID3D11ClassInstance* psInst[256] = {};
    UINT psInstCount = 256;
    ID3D11GeometryShader* gs = nullptr;
    ID3D11ClassInstance* gsInst[256] = {};
    UINT gsInstCount = 256;
    ID3D11HullShader* hs = nullptr;
    ID3D11ClassInstance* hsInst[256] = {};
    UINT hsInstCount = 256;
    ID3D11DomainShader* ds = nullptr;
    ID3D11ClassInstance* dsInst[256] = {};
    UINT dsInstCount = 256;
    ID3D11InputLayout* layout = nullptr;
    D3D11_PRIMITIVE_TOPOLOGY topology = D3D11_PRIMITIVE_TOPOLOGY_UNDEFINED;
    ID3D11Buffer* vb = nullptr;
    UINT vbStride = 0, vbOffset = 0;
    ID3D11Buffer* ib = nullptr;
    DXGI_FORMAT ibFormat = DXGI_FORMAT_UNKNOWN;
    UINT ibOffset = 0;
    ID3D11Buffer* vsCb = nullptr;
    ID3D11Buffer* psCb = nullptr;
    ID3D11ShaderResourceView* psSrv = nullptr;
    ID3D11SamplerState* psSampler = nullptr;

    void Capture(ID3D11DeviceContext* c) {
        c->OMGetRenderTargets(D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT, rtv, &dsv);
        c->RSGetViewports(&numViewports, viewports);
        c->RSGetScissorRects(&numScissors, scissors);
        c->OMGetBlendState(&blend, blendFactor, &sampleMask);
        c->OMGetDepthStencilState(&depth, &stencilRef);
        c->RSGetState(&raster);
        c->VSGetShader(&vs, vsInst, &vsInstCount);
        c->PSGetShader(&ps, psInst, &psInstCount);
        c->GSGetShader(&gs, gsInst, &gsInstCount);
        c->HSGetShader(&hs, hsInst, &hsInstCount);
        c->DSGetShader(&ds, dsInst, &dsInstCount);
        c->IAGetInputLayout(&layout);
        c->IAGetPrimitiveTopology(&topology);
        c->IAGetVertexBuffers(0, 1, &vb, &vbStride, &vbOffset);
        c->IAGetIndexBuffer(&ib, &ibFormat, &ibOffset);
        c->VSGetConstantBuffers(0, 1, &vsCb);
        c->PSGetConstantBuffers(0, 1, &psCb);
        c->PSGetShaderResources(0, 1, &psSrv);
        c->PSGetSamplers(0, 1, &psSampler);
    }

    void Restore(ID3D11DeviceContext* c) {
        c->OMSetRenderTargets(D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT, rtv, dsv);
        c->RSSetViewports(numViewports, viewports);
        c->RSSetScissorRects(numScissors, scissors);
        c->OMSetBlendState(blend, blendFactor, sampleMask);
        c->OMSetDepthStencilState(depth, stencilRef);
        c->RSSetState(raster);
        c->VSSetShader(vs, vsInst, vsInstCount);
        c->PSSetShader(ps, psInst, psInstCount);
        c->GSSetShader(gs, gsInst, gsInstCount);
        c->HSSetShader(hs, hsInst, hsInstCount);
        c->DSSetShader(ds, dsInst, dsInstCount);
        c->IASetInputLayout(layout);
        c->IASetPrimitiveTopology(topology);
        c->IASetVertexBuffers(0, 1, &vb, &vbStride, &vbOffset);
        c->IASetIndexBuffer(ib, ibFormat, ibOffset);
        c->VSSetConstantBuffers(0, 1, &vsCb);
        c->PSSetConstantBuffers(0, 1, &psCb);
        c->PSSetShaderResources(0, 1, &psSrv);
        c->PSSetSamplers(0, 1, &psSampler);

        // Get* AddRef'd everything; drop those references.
        for (auto*& r : rtv) SafeRelease(r);
        SafeRelease(dsv);
        SafeRelease(blend);
        SafeRelease(depth);
        SafeRelease(raster);
        SafeRelease(vs);
        SafeRelease(ps);
        SafeRelease(gs);
        SafeRelease(hs);
        SafeRelease(ds);
        for (UINT i = 0; i < vsInstCount; ++i) SafeRelease(vsInst[i]);
        for (UINT i = 0; i < psInstCount; ++i) SafeRelease(psInst[i]);
        for (UINT i = 0; i < gsInstCount; ++i) SafeRelease(gsInst[i]);
        for (UINT i = 0; i < hsInstCount; ++i) SafeRelease(hsInst[i]);
        for (UINT i = 0; i < dsInstCount; ++i) SafeRelease(dsInst[i]);
        SafeRelease(layout);
        SafeRelease(vb);
        SafeRelease(ib);
        SafeRelease(vsCb);
        SafeRelease(psCb);
        SafeRelease(psSrv);
        SafeRelease(psSampler);
    }
};

struct Resources {
    ID3D11Device* device = nullptr;  // not AddRef'd beyond our objects; compared to detect a new device
    ID3D11VertexShader* vs = nullptr;
    ID3D11PixelShader* ps = nullptr;
    ID3D11InputLayout* layout = nullptr;
    ID3D11Buffer* vb = nullptr;
    ID3D11Buffer* cb = nullptr;
    ID3D11ShaderResourceView* fontSrv = nullptr;
    ID3D11SamplerState* sampler = nullptr;
    ID3D11BlendState* blend = nullptr;
    ID3D11RasterizerState* raster = nullptr;
    ID3D11DepthStencilState* depth = nullptr;
    // backbuffer target (dropped before ResizeBuffers)
    ID3D11Texture2D* backbuffer = nullptr;
    ID3D11RenderTargetView* rtv = nullptr;
    UINT width = 0, height = 0;

    void ReleaseTarget() {
        SafeRelease(rtv);
        SafeRelease(backbuffer);
    }
    void ReleaseAll() {
        ReleaseTarget();
        SafeRelease(vs);
        SafeRelease(ps);
        SafeRelease(layout);
        SafeRelease(vb);
        SafeRelease(cb);
        SafeRelease(fontSrv);
        SafeRelease(sampler);
        SafeRelease(blend);
        SafeRelease(raster);
        SafeRelease(depth);
        device = nullptr;
    }
};

Resources _res;
bool _disabled = false;
bool _loggedFirstDraw = false;
std::vector<Vertex> _verts;

bool Check(HRESULT hr, const char* what) {
    if (SUCCEEDED(hr)) return true;
    MC_LOG_ERROR("overlay: %s failed: 0x%08lx; overlay disabled", what, static_cast<unsigned long>(hr));
    _disabled = true;
    return false;
}

bool CreateResources(ID3D11Device* dev) {
    _res.ReleaseAll();
    if (!Check(dev->CreateVertexShader(kOverlayVS, sizeof(kOverlayVS), nullptr, &_res.vs), "CreateVertexShader") ||
        !Check(dev->CreatePixelShader(kOverlayPS, sizeof(kOverlayPS), nullptr, &_res.ps), "CreatePixelShader")) {
        return false;
    }
    const D3D11_INPUT_ELEMENT_DESC layout[] = {
        {"POSITION", 0, DXGI_FORMAT_R32G32_FLOAT, 0, offsetof(Vertex, x), D3D11_INPUT_PER_VERTEX_DATA, 0},
        {"TEXCOORD", 0, DXGI_FORMAT_R32G32_FLOAT, 0, offsetof(Vertex, u), D3D11_INPUT_PER_VERTEX_DATA, 0},
        {"COLOR", 0, DXGI_FORMAT_R8G8B8A8_UNORM, 0, offsetof(Vertex, color), D3D11_INPUT_PER_VERTEX_DATA, 0},
    };
    if (!Check(dev->CreateInputLayout(layout, 3, kOverlayVS, sizeof(kOverlayVS), &_res.layout), "CreateInputLayout")) {
        return false;
    }

    D3D11_BUFFER_DESC bd{};
    bd.ByteWidth = sizeof(Vertex) * 6 * kMaxQuads;
    bd.Usage = D3D11_USAGE_DYNAMIC;
    bd.BindFlags = D3D11_BIND_VERTEX_BUFFER;
    bd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
    if (!Check(dev->CreateBuffer(&bd, nullptr, &_res.vb), "CreateBuffer(vertices)")) return false;
    bd.ByteWidth = 16;
    bd.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
    if (!Check(dev->CreateBuffer(&bd, nullptr, &_res.cb), "CreateBuffer(constants)")) return false;

    // Font atlas: 16 cells per row, R8 coverage.
    std::vector<uint8_t> atlas(kAtlasW * kAtlasH, 0);
    for (int i = 0; i < font::kCount; ++i) {
        int ox = (i % kAtlasCols) * font::kCellW, oy = (i / kAtlasCols) * font::kCellH;
        for (int y = 0; y < font::kCellH; ++y)
            for (int x = 0; x < font::kCellW; ++x)
                atlas[(oy + y) * kAtlasW + ox + x] = font::kPixels[(i * font::kCellH + y) * font::kCellW + x];
    }
    D3D11_TEXTURE2D_DESC td{};
    td.Width = kAtlasW;
    td.Height = kAtlasH;
    td.MipLevels = 1;
    td.ArraySize = 1;
    td.Format = DXGI_FORMAT_R8_UNORM;
    td.SampleDesc.Count = 1;
    td.Usage = D3D11_USAGE_IMMUTABLE;
    td.BindFlags = D3D11_BIND_SHADER_RESOURCE;
    D3D11_SUBRESOURCE_DATA init{atlas.data(), kAtlasW, 0};
    ID3D11Texture2D* tex = nullptr;
    if (!Check(dev->CreateTexture2D(&td, &init, &tex), "CreateTexture2D(font)")) return false;
    HRESULT hr = dev->CreateShaderResourceView(tex, nullptr, &_res.fontSrv);
    tex->Release();
    if (!Check(hr, "CreateShaderResourceView(font)")) return false;

    D3D11_SAMPLER_DESC sd{};
    sd.Filter = D3D11_FILTER_MIN_MAG_MIP_POINT;
    sd.AddressU = sd.AddressV = sd.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
    sd.MaxLOD = D3D11_FLOAT32_MAX;
    if (!Check(dev->CreateSamplerState(&sd, &_res.sampler), "CreateSamplerState")) return false;

    D3D11_BLEND_DESC bld{};
    auto& rt = bld.RenderTarget[0];
    rt.BlendEnable = TRUE;
    rt.SrcBlend = D3D11_BLEND_SRC_ALPHA;
    rt.DestBlend = D3D11_BLEND_INV_SRC_ALPHA;
    rt.BlendOp = D3D11_BLEND_OP_ADD;
    rt.SrcBlendAlpha = D3D11_BLEND_ONE;
    rt.DestBlendAlpha = D3D11_BLEND_INV_SRC_ALPHA;
    rt.BlendOpAlpha = D3D11_BLEND_OP_ADD;
    rt.RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
    if (!Check(dev->CreateBlendState(&bld, &_res.blend), "CreateBlendState")) return false;

    D3D11_RASTERIZER_DESC rd{};
    rd.FillMode = D3D11_FILL_SOLID;
    rd.CullMode = D3D11_CULL_NONE;
    rd.DepthClipEnable = TRUE;
    if (!Check(dev->CreateRasterizerState(&rd, &_res.raster), "CreateRasterizerState")) return false;

    D3D11_DEPTH_STENCIL_DESC dsd{};
    dsd.DepthEnable = FALSE;
    dsd.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ZERO;
    dsd.DepthFunc = D3D11_COMPARISON_ALWAYS;
    if (!Check(dev->CreateDepthStencilState(&dsd, &_res.depth), "CreateDepthStencilState")) return false;

    _res.device = dev;
    MC_LOG_INFO("overlay: resources created on device %p (font atlas %dx%d)", dev, kAtlasW, kAtlasH);
    return true;
}

// RTVs cannot be created for typeless formats; pick the plain UNORM/FLOAT view of the backbuffer.
DXGI_FORMAT ViewFormat(DXGI_FORMAT f) {
    switch (f) {
    case DXGI_FORMAT_R8G8B8A8_TYPELESS: return DXGI_FORMAT_R8G8B8A8_UNORM;
    case DXGI_FORMAT_B8G8R8A8_TYPELESS: return DXGI_FORMAT_B8G8R8A8_UNORM;
    case DXGI_FORMAT_B8G8R8X8_TYPELESS: return DXGI_FORMAT_B8G8R8X8_UNORM;
    case DXGI_FORMAT_R10G10B10A2_TYPELESS: return DXGI_FORMAT_R10G10B10A2_UNORM;
    case DXGI_FORMAT_R16G16B16A16_TYPELESS: return DXGI_FORMAT_R16G16B16A16_FLOAT;
    default: return f;
    }
}

bool EnsureTarget(IDXGISwapChain* sc, ID3D11Device* dev) {
    ID3D11Texture2D* bb = nullptr;
    if (FAILED(sc->GetBuffer(0, __uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&bb))) || !bb) return false;
    if (bb == _res.backbuffer && _res.rtv) {
        bb->Release();
        return true;
    }
    _res.ReleaseTarget();
    D3D11_TEXTURE2D_DESC td{};
    bb->GetDesc(&td);
    D3D11_RENDER_TARGET_VIEW_DESC rd{};
    rd.Format = ViewFormat(td.Format);
    rd.ViewDimension = td.SampleDesc.Count > 1 ? D3D11_RTV_DIMENSION_TEXTURE2DMS : D3D11_RTV_DIMENSION_TEXTURE2D;
    HRESULT hr = dev->CreateRenderTargetView(bb, &rd, &_res.rtv);
    if (FAILED(hr)) {
        bb->Release();
        Check(hr, "CreateRenderTargetView(backbuffer)");
        return false;
    }
    _res.backbuffer = bb;  // keeps our reference until ReleaseTargets()
    _res.width = td.Width;
    _res.height = td.Height;
    MC_LOG_INFO("overlay: target %ux%u format %d", td.Width, td.Height, static_cast<int>(td.Format));
    return true;
}

uint32_t ToRgba(uint32_t argb) {
    // 0xAARRGGBB -> bytes r, g, b, a in memory (little-endian uint32 0xAABBGGRR)
    return (argb & 0xFF00FF00u) | ((argb >> 16) & 0xFFu) | ((argb & 0xFFu) << 16);
}

void PushQuad(float x0, float y0, float x1, float y1, int cell, uint32_t color) {
    if (_verts.size() + 6 > static_cast<size_t>(kMaxQuads) * 6) return;
    float u0 = static_cast<float>((cell % kAtlasCols) * font::kCellW) / kAtlasW;
    float v0 = static_cast<float>((cell / kAtlasCols) * font::kCellH) / kAtlasH;
    float u1 = u0 + static_cast<float>(font::kCellW) / kAtlasW;
    float v1 = v0 + static_cast<float>(font::kCellH) / kAtlasH;
    if (cell == font::kSolid) {  // sample the middle of the solid cell only
        float cu = (u0 + u1) * 0.5f, cv = (v0 + v1) * 0.5f;
        u0 = u1 = cu;
        v0 = v1 = cv;
    }
    const Vertex a{x0, y0, u0, v0, color}, b{x1, y0, u1, v0, color}, c{x0, y1, u0, v1, color},
        d{x1, y1, u1, v1, color};
    _verts.insert(_verts.end(), {a, b, c, c, b, d});
}

// Decodes UTF-8 to atlas cells: ASCII as is, em/en dash -> '-', anything else -> '?'.
void ToCells(const std::string& s, std::vector<int>& cells) {
    cells.clear();
    for (size_t i = 0; i < s.size();) {
        unsigned char ch = static_cast<unsigned char>(s[i]);
        if (ch < 0x80) {
            cells.push_back(ch >= font::kFirst && ch < font::kFirst + font::kSolid ? ch - font::kFirst : '?' - font::kFirst);
            ++i;
            continue;
        }
        size_t len = ch >= 0xF0 ? 4 : ch >= 0xE0 ? 3 : ch >= 0xC0 ? 2 : 1;
        bool dash = len == 3 && i + 2 < s.size() && ch == 0xE2 && static_cast<unsigned char>(s[i + 1]) == 0x80 &&
                    (static_cast<unsigned char>(s[i + 2]) == 0x93 || static_cast<unsigned char>(s[i + 2]) == 0x94);
        cells.push_back((dash ? '-' : '?') - font::kFirst);
        i += len;
    }
}

} // namespace

void Overlay::ReleaseTargets() { _res.ReleaseTarget(); }

void Overlay::Draw(IDXGISwapChain* sc, const std::vector<OverlayLine>& lines) {
    if (_disabled || !sc || lines.empty()) return;

    ID3D11Device* dev = nullptr;
    if (FAILED(sc->GetDevice(__uuidof(ID3D11Device), reinterpret_cast<void**>(&dev))) || !dev) {
        MC_LOG_WARN("overlay: swapchain has no D3D11 device; overlay disabled");
        _disabled = true;
        return;
    }
    if (dev != _res.device && !CreateResources(dev)) {
        dev->Release();
        return;
    }
    if (!EnsureTarget(sc, dev)) {
        dev->Release();
        return;
    }
    ID3D11DeviceContext* ctx = nullptr;
    dev->GetImmediateContext(&ctx);
    dev->Release();  // our resources keep the device alive while we use it
    if (!ctx) return;

    // ---- build geometry ----
    const float scale = static_cast<float>(std::max(1u, (_res.height + 540u) / 1080u));
    const float cw = font::kCellW * scale, ch = font::kCellH * scale;
    size_t maxChars = 0;
    std::vector<std::vector<int>> cells(lines.size());
    for (size_t i = 0; i < lines.size(); ++i) {
        ToCells(lines[i].text, cells[i]);
        maxChars = std::max(maxChars, cells[i].size());
    }
    _verts.clear();
    const float x0 = kMargin, y0 = kMargin;
    PushQuad(x0, y0, x0 + kPad * 2 + cw * maxChars, y0 + kPad * 2 + ch * lines.size(), font::kSolid, ToRgba(0xA0000000));
    for (size_t i = 0; i < lines.size(); ++i) {
        float y = y0 + kPad + ch * i;
        float x = x0 + kPad;
        uint32_t color = ToRgba(lines[i].color);
        uint32_t shadow = ToRgba(0xC0000000);
        for (int c : cells[i]) {
            if (c != 0) {  // skip spaces
                PushQuad(x + scale, y + scale, x + cw + scale, y + ch + scale, c, shadow);
                PushQuad(x, y, x + cw, y + ch, c, color);
            }
            x += cw;
        }
    }

    D3D11_MAPPED_SUBRESOURCE m{};
    if (FAILED(ctx->Map(_res.vb, 0, D3D11_MAP_WRITE_DISCARD, 0, &m))) {
        ctx->Release();
        return;
    }
    memcpy(m.pData, _verts.data(), _verts.size() * sizeof(Vertex));
    ctx->Unmap(_res.vb, 0);
    if (SUCCEEDED(ctx->Map(_res.cb, 0, D3D11_MAP_WRITE_DISCARD, 0, &m))) {
        float* f = static_cast<float*>(m.pData);
        f[0] = 1.0f / static_cast<float>(_res.width);
        f[1] = 1.0f / static_cast<float>(_res.height);
        f[2] = f[3] = 0.0f;
        ctx->Unmap(_res.cb, 0);
    }

    // ---- draw with our state, then put the game's back ----
    SavedState* saved = new SavedState;  // ~6 KB of slots; heap keeps the render thread's stack small
    saved->Capture(ctx);

    D3D11_VIEWPORT vp{0, 0, static_cast<float>(_res.width), static_cast<float>(_res.height), 0, 1};
    const UINT stride = sizeof(Vertex), offset = 0;
    const float blendFactor[4] = {0, 0, 0, 0};
    ctx->OMSetRenderTargets(1, &_res.rtv, nullptr);
    ctx->RSSetViewports(1, &vp);
    ctx->OMSetBlendState(_res.blend, blendFactor, 0xFFFFFFFF);
    ctx->OMSetDepthStencilState(_res.depth, 0);
    ctx->RSSetState(_res.raster);
    ctx->IASetInputLayout(_res.layout);
    ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    ctx->IASetVertexBuffers(0, 1, &_res.vb, &stride, &offset);
    ctx->IASetIndexBuffer(nullptr, DXGI_FORMAT_UNKNOWN, 0);
    ctx->VSSetShader(_res.vs, nullptr, 0);
    ctx->VSSetConstantBuffers(0, 1, &_res.cb);
    ctx->PSSetShader(_res.ps, nullptr, 0);
    ctx->PSSetShaderResources(0, 1, &_res.fontSrv);
    ctx->PSSetSamplers(0, 1, &_res.sampler);
    ctx->GSSetShader(nullptr, nullptr, 0);
    ctx->HSSetShader(nullptr, nullptr, 0);
    ctx->DSSetShader(nullptr, nullptr, 0);
    ctx->Draw(static_cast<UINT>(_verts.size()), 0);

    saved->Restore(ctx);
    delete saved;
    ctx->Release();

    if (!_loggedFirstDraw) {
        _loggedFirstDraw = true;
        MC_LOG_INFO("overlay: first draw (%zu lines, %zu vertices, scale %.0f): '%s'", lines.size(), _verts.size(),
                    scale, lines[0].text.c_str());
    }
}

} // namespace mc::render
